import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];
  const disposables = [];

  // === BACKDROP PLANE WITH GRADIENT ===
  const backdropGeom = new THREE.PlaneGeometry(7, 5.5);
  const gradientTexture = createGradientTexture(512, 512);
  disposables.push(gradientTexture);

  const backdropMat = new THREE.MeshBasicMaterial({
    map: gradientTexture,
    side: THREE.FrontSide,
    toneMapped: false
  });
  disposables.push(backdropMat);

  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -1.5;
  group.add(backdrop);
  disposables.push(backdropGeom);

  // === TEXT RENDERING ===
  let maxGlyphTime = 0;

  // Caption kicker
  const captionMesh = createTextMesh(ctx, {
    text: "NOVA ATELIER / CALIBRE PROGRAM",
    family: "JetBrains Mono",
    size: 18,
    weight: 700,
    color: "#e8ecf2"
  });
  if (captionMesh) {
    captionMesh.position.y = 1.15;
    captionMesh.position.z = 0;
    centerMesh(captionMesh);
    group.add(captionMesh);
    disposables.push(captionMesh);

    const captionTL = gsap.timeline();
    captionTL.fromTo(
      captionMesh,
      { opacity: 0, y: 1.35 },
      { opacity: 1, y: 1.15, duration: 0.5, ease: "cubic-bezier(0.25,0.46,0.45,0.94)" },
      0.5
    );
    timelines.push(captionTL);
  }

  // Hero text with per-word depth parallax
  const heroText = "TIME, MACHINED.";
  const heroWords = heroText.split(/(\s+)/);
  const heroZOffsets = [0.12, 0.0, -0.12];
  let wordCount = 0;

  heroWords.forEach((word) => {
    if (!word.trim()) return;

    const heroMesh = createTextMesh(ctx, {
      text: word,
      family: "Lora",
      size: 124,
      weight: 600,
      color: "#e8ecf2"
    });

    if (heroMesh) {
      const zOffset = heroZOffsets[wordCount % heroZOffsets.length];
      heroMesh.position.set(0, 0.4, zOffset);
      centerMesh(heroMesh);
      group.add(heroMesh);
      disposables.push(heroMesh);

      // Per-word kinetic animation: 60ms stagger
      const staggerTime = wordCount * 0.06;
      const heroTL = gsap.timeline();
      heroTL.fromTo(
        heroMesh,
        { opacity: 0, y: 0.75 },
        {
          opacity: 1,
          y: 0.4,
          duration: 0.7,
          ease: "cubic-bezier(0.215,0.61,0.355,1)"
        },
        staggerTime
      );
      timelines.push(heroTL);

      maxGlyphTime = Math.max(maxGlyphTime, staggerTime + 0.7);
      wordCount++;
    }
  });

  // Subhead
  const subheadMesh = createTextMesh(ctx, {
    text: "Every calibre begins as a solid billet.",
    family: "JetBrains Mono",
    size: 40,
    weight: 400,
    color: "#e8ecf2"
  });
  if (subheadMesh) {
    subheadMesh.position.y = -0.65;
    subheadMesh.position.z = 0;
    centerMesh(subheadMesh);
    group.add(subheadMesh);
    disposables.push(subheadMesh);

    const subTL = gsap.timeline();
    subTL.fromTo(
      subheadMesh,
      { opacity: 0, y: -0.45 },
      { opacity: 1, y: -0.65, duration: 0.5, ease: "cubic-bezier(0.25,0.46,0.45,0.94)" },
      0.3
    );
    timelines.push(subTL);
  }

  // === ACCENT UNDERLINE ===
  const underlineGeom = new THREE.PlaneGeometry(2.6, 0.045);
  const underlineMat = new THREE.MeshBasicMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.2,
    side: THREE.FrontSide,
    toneMapped: false
  });
  disposables.push(underlineMat);

  const underline = new THREE.Mesh(underlineGeom, underlineMat);
  underline.position.set(0, -0.05, 0);
  underline.scale.x = 0;
  group.add(underline);
  disposables.push(underlineGeom);

  // Underline reveal: 120ms after last glyph lands
  const ulTL = gsap.timeline();
  ulTL.to(
    underline.scale,
    {
      x: 1,
      duration: 0.5,
      ease: "cubic-bezier(0.25,0.46,0.45,0.94)"
    },
    maxGlyphTime + 0.12
  );
  timelines.push(ulTL);

  // === WEIGHTED SETTLE ===
  group.scale.set(1.04, 1.04, 1.04);
  const settleTL = gsap.timeline();
  settleTL.to(
    group.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: "cubic-bezier(0.165,0.84,0.44,1)"
    },
    maxGlyphTime
  );
  timelines.push(settleTL);

  // === CINEMATIC PRIMITIVES ===
  if (config.cinematicPrimitives?.length > 0) {
    config.cinematicPrimitives.forEach(({ name, params }) => {
      if (ctx.primitives?.[name]) {
        ctx.primitives[name](group, params || {});
      }
    });
  }

  // === CLEANUP ===
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    disposables.forEach(item => {
      if (item.dispose) item.dispose();
    });
  };

  return group;
}

function createTextMesh(ctx, options) {
  if (!ctx?.fontAtlas?.createText) return null;

  try {
    return ctx.fontAtlas.createText({
      text: options.text,
      fontFamily: options.family,
      fontSize: options.size,
      fontWeight: options.weight,
      color: options.color
    });
  } catch (e) {
    return null;
  }
}

function centerMesh(mesh) {
  if (mesh.geometry) {
    if (!mesh.geometry.boundingBox) {
      mesh.geometry.computeBoundingBox();
    }
    mesh.geometry.center();
  }
}

function createGradientTexture(width, height) {
  const data = new Uint8Array(width * height * 4);

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const idx = (y * width + x) * 4;
      const t = y / height;

      // Vertical gradient #0b0b10 → #13131a
      const r = Math.round(0x0b + (0x13 - 0x0b) * t);
      const g = Math.round(0x0b + (0x13 - 0x0b) * t);
      const b = Math.round(0x10 + (0x1a - 0x10) * t);

      // Mono grain: 1.5%
      const grain = (Math.random() - 0.5) * 2 * 0.015 * 255;

      data[idx] = Math.max(0, Math.min(255, r + grain));
      data[idx + 1] = Math.max(0, Math.min(255, g + grain));
      data[idx + 2] = Math.max(0, Math.min(255, b + grain));
      data[idx + 3] = 255;
    }
  }

  const texture = new THREE.DataTexture(data, width, height, THREE.RGBAFormat);
  texture.needsUpdate = true;
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearFilter;
  return texture;
}
